import{_ as t,o as a,c as s,a4 as i}from"./chunks/framework.BHRp8ZZT.js";const c=JSON.parse(`{"title":"Feuille de Route d'Apprentissage en 52 Semaines (Roadmap)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/03_Roadmap.md","filePath":"fr/03_Roadmap.md","lastUpdated":1788996924000}`),n={name:"fr/03_Roadmap.md"};function r(o,e,l,d,u,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="feuille-de-route-d-apprentissage-en-52-semaines-roadmap" tabindex="-1">Feuille de Route d&#39;Apprentissage en 52 Semaines (Roadmap) <a class="header-anchor" href="#feuille-de-route-d-apprentissage-en-52-semaines-roadmap" aria-label="Permalink to &quot;Feuille de Route d&#39;Apprentissage en 52 Semaines (Roadmap)&quot;">​</a></h1><blockquote><p><em>Plan progressif sur 52 semaines : prérequis, composants, systèmes distribués, cas pratiques et entretiens.</em></p></blockquote><hr><p><strong>Phases de la Feuille de Route</strong>: 14</p><h2 id="📅-chronologie-generale" tabindex="-1">📅 Chronologie Générale <a class="header-anchor" href="#📅-chronologie-generale" aria-label="Permalink to &quot;📅 Chronologie Générale&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Phase</th><th style="text-align:left;">Période</th><th style="text-align:left;">Thème</th><th style="text-align:left;">Jalon / Preuve</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Phase 0</strong></td><td style="text-align:left;"><code>Weeks 1-3</code></td><td style="text-align:left;"><strong>Prerequisites and vocabulary</strong></td><td style="text-align:left;">You can explain what happens when you type a URL, in detail.</td></tr><tr><td style="text-align:left;"><strong>Phase 0</strong></td><td style="text-align:left;"><code>Weeks 3-6</code></td><td style="text-align:left;"><strong>Estimation and requirements</strong></td><td style="text-align:left;">You can size a system in five minutes with defensible numbers.</td></tr><tr><td style="text-align:left;"><strong>Phase 1</strong></td><td style="text-align:left;"><code>Weeks 6-10</code></td><td style="text-align:left;"><strong>The building blocks</strong></td><td style="text-align:left;">You can name the right component for a requirement without hesitating.</td></tr><tr><td style="text-align:left;"><strong>Phase 1</strong></td><td style="text-align:left;"><code>Weeks 10-14</code></td><td style="text-align:left;"><strong>Databases in depth</strong></td><td style="text-align:left;">You can defend a database choice against a challenging follow-up.</td></tr><tr><td style="text-align:left;"><strong>Phase 2</strong></td><td style="text-align:left;"><code>Weeks 14-18</code></td><td style="text-align:left;"><strong>Distributed systems theory</strong></td><td style="text-align:left;">You understand why distributed systems are hard, not just that they are.</td></tr><tr><td style="text-align:left;"><strong>Phase 2</strong></td><td style="text-align:left;"><code>Weeks 18-22</code></td><td style="text-align:left;"><strong>Caching and messaging</strong></td><td style="text-align:left;">You can explain cache invalidation and exactly-once honestly, including the caveats.</td></tr><tr><td style="text-align:left;"><strong>Phase 3</strong></td><td style="text-align:left;"><code>Weeks 22-28</code></td><td style="text-align:left;"><strong>Core case studies</strong></td><td style="text-align:left;">You can design any of the classic eight from a blank page in 45 minutes.</td></tr><tr><td style="text-align:left;"><strong>Phase 3</strong></td><td style="text-align:left;"><code>Weeks 28-32</code></td><td style="text-align:left;"><strong>Harder case studies</strong></td><td style="text-align:left;">You can go three follow-up questions deep on any component you drew.</td></tr><tr><td style="text-align:left;"><strong>Phase 4</strong></td><td style="text-align:left;"><code>Weeks 32-35</code></td><td style="text-align:left;"><strong>Reliability and operations</strong></td><td style="text-align:left;">Every design you produce now includes a failure discussion unprompted.</td></tr><tr><td style="text-align:left;"><strong>Phase 4</strong></td><td style="text-align:left;"><code>Weeks 35-38</code></td><td style="text-align:left;"><strong>Observability and security</strong></td><td style="text-align:left;">You can answer &#39;how would you know it broke&#39; for any system you design.</td></tr><tr><td style="text-align:left;"><strong>Phase 5</strong></td><td style="text-align:left;"><code>Weeks 38-42</code></td><td style="text-align:left;"><strong>Low level design</strong></td><td style="text-align:left;">You can produce a clean class design and defend each abstraction.</td></tr><tr><td style="text-align:left;"><strong>Phase 5</strong></td><td style="text-align:left;"><code>Weeks 42-45</code></td><td style="text-align:left;"><strong>Real architectures</strong></td><td style="text-align:left;">You can cite how a real company solved a problem you are designing.</td></tr><tr><td style="text-align:left;"><strong>Phase 6</strong></td><td style="text-align:left;"><code>Weeks 45-48</code></td><td style="text-align:left;"><strong>Mock interviews</strong></td><td style="text-align:left;">You can fill 45 minutes with structure, not filler.</td></tr><tr><td style="text-align:left;"><strong>Phase 6</strong></td><td style="text-align:left;"><code>Weeks 48-52</code></td><td style="text-align:left;"><strong>Company-specific preparation</strong></td><td style="text-align:left;">You can connect your design choices to that company&#39;s actual problems.</td></tr></tbody></table><hr><h2 id="📖-plan-detaille-phase-par-phase" tabindex="-1">📖 Plan Détaillé Phase par Phase <a class="header-anchor" href="#📖-plan-detaille-phase-par-phase" aria-label="Permalink to &quot;📖 Plan Détaillé Phase par Phase&quot;">​</a></h2><h3 id="phase-0-weeks-1-3-prerequisites-and-vocabulary" tabindex="-1">Phase 0 (Weeks 1-3): Prerequisites and vocabulary <a class="header-anchor" href="#phase-0-weeks-1-3-prerequisites-and-vocabulary" aria-label="Permalink to &quot;Phase 0 (Weeks 1-3): Prerequisites and vocabulary&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Client-server, DNS, HTTP, TLS, REST, databases, what a server actually is. Latency numbers every programmer should know.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Write out the request path for a website you use, end to end, from keystroke to pixel.</li><li>🎯 <strong>Jalon / Validation</strong>: You can explain what happens when you type a URL, in detail.</li></ul><h3 id="phase-0-weeks-3-6-estimation-and-requirements" tabindex="-1">Phase 0 (Weeks 3-6): Estimation and requirements <a class="header-anchor" href="#phase-0-weeks-3-6-estimation-and-requirements" aria-label="Permalink to &quot;Phase 0 (Weeks 3-6): Estimation and requirements&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Back-of-the-envelope maths, QPS, storage and bandwidth estimation, functional versus non-functional requirements.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Estimate storage, QPS and bandwidth for three products you use daily. Check your assumptions.</li><li>🎯 <strong>Jalon / Validation</strong>: You can size a system in five minutes with defensible numbers.</li></ul><h3 id="phase-1-weeks-6-10-the-building-blocks" tabindex="-1">Phase 1 (Weeks 6-10): The building blocks <a class="header-anchor" href="#phase-1-weeks-6-10-the-building-blocks" aria-label="Permalink to &quot;Phase 1 (Weeks 6-10): The building blocks&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Load balancers, caches, CDNs, proxies, API gateways, message queues, object storage. What each does and costs.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: For each block, write when you would use it, when you would not, and what it fails at.</li><li>🎯 <strong>Jalon / Validation</strong>: You can name the right component for a requirement without hesitating.</li></ul><h3 id="phase-1-weeks-10-14-databases-in-depth" tabindex="-1">Phase 1 (Weeks 10-14): Databases in depth <a class="header-anchor" href="#phase-1-weeks-10-14-databases-in-depth" aria-label="Permalink to &quot;Phase 1 (Weeks 10-14): Databases in depth&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: SQL versus NoSQL, indexing, replication, sharding, consistent hashing, transactions, isolation, hot partitions.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Design schemas and sharding strategies for three different products. Justify each partition key.</li><li>🎯 <strong>Jalon / Validation</strong>: You can defend a database choice against a challenging follow-up.</li></ul><h3 id="phase-2-weeks-14-18-distributed-systems-theory" tabindex="-1">Phase 2 (Weeks 14-18): Distributed systems theory <a class="header-anchor" href="#phase-2-weeks-14-18-distributed-systems-theory" aria-label="Permalink to &quot;Phase 2 (Weeks 14-18): Distributed systems theory&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: CAP and PACELC, consistency models, consensus, leader election, quorums, replication lag, clock problems.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Watch the Martin Kleppmann lecture series. Read the DDIA chapters on replication and consistency.</li><li>🎯 <strong>Jalon / Validation</strong>: You understand why distributed systems are hard, not just that they are.</li></ul><h3 id="phase-2-weeks-18-22-caching-and-messaging" tabindex="-1">Phase 2 (Weeks 18-22): Caching and messaging <a class="header-anchor" href="#phase-2-weeks-18-22-caching-and-messaging" aria-label="Permalink to &quot;Phase 2 (Weeks 18-22): Caching and messaging&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Cache strategies, invalidation, eviction, multi-level caching, Kafka, queues, delivery guarantees, idempotency.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Design the caching layer and the event flow for a product you know well.</li><li>🎯 <strong>Jalon / Validation</strong>: You can explain cache invalidation and exactly-once honestly, including the caveats.</li></ul><h3 id="phase-3-weeks-22-28-core-case-studies" tabindex="-1">Phase 3 (Weeks 22-28): Core case studies <a class="header-anchor" href="#phase-3-weeks-22-28-core-case-studies" aria-label="Permalink to &quot;Phase 3 (Weeks 22-28): Core case studies&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: URL shortener, rate limiter, pastebin, key-value store, web crawler, notification system, chat, news feed.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Work through the first 15 case studies on the Case Studies sheet. Write each one up before checking a solution.</li><li>🎯 <strong>Jalon / Validation</strong>: You can design any of the classic eight from a blank page in 45 minutes.</li></ul><h3 id="phase-3-weeks-28-32-harder-case-studies" tabindex="-1">Phase 3 (Weeks 28-32): Harder case studies <a class="header-anchor" href="#phase-3-weeks-28-32-harder-case-studies" aria-label="Permalink to &quot;Phase 3 (Weeks 28-32): Harder case studies&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Uber, Netflix, WhatsApp, Google Docs, search, payments, ticket booking, distributed scheduler.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Work through the remaining case studies. Focus on the deep dive rather than the boxes.</li><li>🎯 <strong>Jalon / Validation</strong>: You can go three follow-up questions deep on any component you drew.</li></ul><h3 id="phase-4-weeks-32-35-reliability-and-operations" tabindex="-1">Phase 4 (Weeks 32-35): Reliability and operations <a class="header-anchor" href="#phase-4-weeks-32-35-reliability-and-operations" aria-label="Permalink to &quot;Phase 4 (Weeks 32-35): Reliability and operations&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Redundancy, circuit breakers, rate limiting, graceful degradation, backpressure, disaster recovery, chaos.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Take three of your designs and add the failure story: what breaks, what the user sees, how it recovers.</li><li>🎯 <strong>Jalon / Validation</strong>: Every design you produce now includes a failure discussion unprompted.</li></ul><h3 id="phase-4-weeks-35-38-observability-and-security" tabindex="-1">Phase 4 (Weeks 35-38): Observability and security <a class="header-anchor" href="#phase-4-weeks-35-38-observability-and-security" aria-label="Permalink to &quot;Phase 4 (Weeks 35-38): Observability and security&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Logging, metrics, tracing, SLOs, alerting, auth at scale, encryption, secrets, DDoS, data privacy.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Add the observability and security layer to your existing designs. Define an SLO for each.</li><li>🎯 <strong>Jalon / Validation</strong>: You can answer &#39;how would you know it broke&#39; for any system you design.</li></ul><h3 id="phase-5-weeks-38-42-low-level-design" tabindex="-1">Phase 5 (Weeks 38-42): Low level design <a class="header-anchor" href="#phase-5-weeks-38-42-low-level-design" aria-label="Permalink to &quot;Phase 5 (Weeks 38-42): Low level design&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: SOLID, design patterns, class diagrams, concurrency in objects, parking lot, elevator, BookMyShow, Splitwise.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Solve 10 LLD problems with full class diagrams and working code. Amazon and Indian companies ask these directly.</li><li>🎯 <strong>Jalon / Validation</strong>: You can produce a clean class design and defend each abstraction.</li></ul><h3 id="phase-5-weeks-42-45-real-architectures" tabindex="-1">Phase 5 (Weeks 42-45): Real architectures <a class="header-anchor" href="#phase-5-weeks-42-45-real-architectures" aria-label="Permalink to &quot;Phase 5 (Weeks 42-45): Real architectures&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Engineering blogs from Netflix, Uber, Airbnb, Discord, Slack, Meta. How production actually differs from textbooks.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Read two engineering blog posts a week. Write a paragraph on what surprised you in each.</li><li>🎯 <strong>Jalon / Validation</strong>: You can cite how a real company solved a problem you are designing.</li></ul><h3 id="phase-6-weeks-45-48-mock-interviews" tabindex="-1">Phase 6 (Weeks 45-48): Mock interviews <a class="header-anchor" href="#phase-6-weeks-45-48-mock-interviews" aria-label="Permalink to &quot;Phase 6 (Weeks 45-48): Mock interviews&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Timed 45-minute designs, thinking out loud, diagramming under pressure, handling challenging follow-ups.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Two mock interviews weekly. Record yourself. Watch it back; it is uncomfortable and effective.</li><li>🎯 <strong>Jalon / Validation</strong>: You can fill 45 minutes with structure, not filler.</li></ul><h3 id="phase-6-weeks-48-52-company-specific-preparation" tabindex="-1">Phase 6 (Weeks 48-52): Company-specific preparation <a class="header-anchor" href="#phase-6-weeks-48-52-company-specific-preparation" aria-label="Permalink to &quot;Phase 6 (Weeks 48-52): Company-specific preparation&quot;">​</a></h3><ul><li>📚 <strong>Ce qu&#39;il faut apprendre</strong>: Target company patterns, their engineering blog, their scale, their known question set. Behavioural preparation.</li><li>🛠️ <strong>Ce qu&#39;il faut faire</strong>: Study your target company&#39;s architecture publicly. Prepare three of your own project stories in depth.</li><li>🎯 <strong>Jalon / Validation</strong>: You can connect your design choices to that company&#39;s actual problems.</li></ul>',36)])])}const p=t(n,[["render",r]]);export{c as __pageData,p as default};
